package storage

import (
	"compress/zlib"
	"fmt"
	"io"
	"os"
	"path/filepath"
)

// Store는 Content-Addressable Storage 엔진
// 실제 Git의 .git/objects/ 와 동일한 구조:
//   .freegit/objects/ab/cdef1234... (앞 2자리 = 폴더, 나머지 = 파일명)
type Store struct {
	RootPath    string // 저장소 루트 (.freegit의 상위)
	ObjectsPath string // .freegit/objects
}

// NewStore는 새 Store 인스턴스를 생성합니다.
func NewStore(rootPath string) *Store {
	return &Store{
		RootPath:    rootPath,
		ObjectsPath: filepath.Join(rootPath, ".freegit", "objects"),
	}
}

// Init은 저장소 디렉토리 구조를 초기화합니다.
// .freegit/
//   objects/
//   refs/heads/
//   refs/tags/
//   HEAD
func (s *Store) Init() error {
	dirs := []string{
		s.ObjectsPath,
		filepath.Join(s.RootPath, ".freegit", "refs", "heads"),
		filepath.Join(s.RootPath, ".freegit", "refs", "tags"),
	}
	for _, dir := range dirs {
		if err := os.MkdirAll(dir, 0755); err != nil {
			return fmt.Errorf("failed to create %s: %w", dir, err)
		}
	}

	// HEAD 초기화 (main 브랜치 기본값)
	headPath := filepath.Join(s.RootPath, ".freegit", "HEAD")
	if _, err := os.Stat(headPath); os.IsNotExist(err) {
		if err := os.WriteFile(headPath, []byte("ref: refs/heads/main\n"), 0644); err != nil {
			return fmt.Errorf("failed to write HEAD: %w", err)
		}
	}

	return nil
}

// Write는 Object를 디스크에 zlib 압축해서 저장합니다.
// 경로: .freegit/objects/{hash[:2]}/{hash[2:]}
func (s *Store) Write(obj *Object) error {
	hash := obj.Hash
	dirPath := filepath.Join(s.ObjectsPath, hash[:2])
	filePath := filepath.Join(dirPath, hash[2:])

	// 이미 존재하면 스킵 (Content-Addressable이라 내용 동일)
	if _, err := os.Stat(filePath); err == nil {
		return nil
	}

	if err := os.MkdirAll(dirPath, 0755); err != nil {
		return fmt.Errorf("failed to create object dir: %w", err)
	}

	f, err := os.Create(filePath)
	if err != nil {
		return fmt.Errorf("failed to create object file: %w", err)
	}
	defer f.Close()

	// zlib 압축 저장 (실제 Git과 동일)
	w := zlib.NewWriter(f)
	defer w.Close()

	if _, err := w.Write(obj.Serialize()); err != nil {
		return fmt.Errorf("failed to write object: %w", err)
	}

	return nil
}

// Read는 해시값으로 Object를 로드합니다.
func (s *Store) Read(hash string) (*Object, error) {
	if len(hash) < 4 {
		return nil, fmt.Errorf("hash too short: %s", hash)
	}

	filePath := filepath.Join(s.ObjectsPath, hash[:2], hash[2:])
	f, err := os.Open(filePath)
	if err != nil {
		return nil, fmt.Errorf("object not found: %s", hash)
	}
	defer f.Close()

	// zlib 압축 해제
	r, err := zlib.NewReader(f)
	if err != nil {
		return nil, fmt.Errorf("failed to decompress object: %w", err)
	}
	defer r.Close()

	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("failed to read object data: %w", err)
	}

	return Deserialize(data)
}

// Exists는 해시에 해당하는 Object가 존재하는지 확인합니다.
func (s *Store) Exists(hash string) bool {
	if len(hash) < 4 {
		return false
	}
	filePath := filepath.Join(s.ObjectsPath, hash[:2], hash[2:])
	_, err := os.Stat(filePath)
	return err == nil
}

// List는 저장된 모든 Object의 해시 목록을 반환합니다.
func (s *Store) List() ([]string, error) {
	var hashes []string

	entries, err := os.ReadDir(s.ObjectsPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read objects dir: %w", err)
	}

	for _, dir := range entries {
		if !dir.IsDir() || len(dir.Name()) != 2 {
			continue
		}
		subDir := filepath.Join(s.ObjectsPath, dir.Name())
		files, err := os.ReadDir(subDir)
		if err != nil {
			continue
		}
		for _, file := range files {
			hashes = append(hashes, dir.Name()+file.Name())
		}
	}

	return hashes, nil
}

