}

// ToObject는 Tree를 저장 가능한 Object로 변환합니다.
// Git Tree 바이너리 형식:
//   "{mode} {name}\x00{20-byte hash binary}" 반복
func (t *Tree) ToObject() *Object {
	var buf bytes.Buffer
	for _, entry := range t.Entries {
		// "{mode} {name}\x00"
		buf.WriteString(fmt.Sprintf("%s %s\x00", entry.Mode, entry.Name))
		// 20바이트 바이너리 해시 (hex → binary)
		hashBytes := hexToBytes(entry.Hash)
		buf.Write(hashBytes)
	}
	return &Object{
		Type:    TreeType,
		Content: buf.Bytes(),
		Hash:    calculateHash(TreeType, buf.Bytes()),
	}
}

// TreeFromObject는 Object에서 Tree를 복원합니다.
func TreeFromObject(obj *Object) (*Tree, error) {
	if obj.Type != TreeType {
		return nil, fmt.Errorf("expected tree, got %s", obj.Type)
	}

	var entries []TreeEntry
	data := obj.Content
	i := 0

	for i < len(data) {
		// mode 파싱 (공백까지)
		spaceIdx := bytes.IndexByte(data[i:], ' ')
		if spaceIdx < 0 {
			return nil, fmt.Errorf("invalid tree entry: missing space")
		}
		mode := string(data[i : i+spaceIdx])
		i += spaceIdx + 1

		// name 파싱 (null byte까지)
		nullIdx := bytes.IndexByte(data[i:], '\x00')
		if nullIdx < 0 {
			return nil, fmt.Errorf("invalid tree entry: missing null byte")
		}
		name := string(data[i : i+nullIdx])
		i += nullIdx + 1

		// 20바이트 binary hash
		if i+20 > len(data) {
			return nil, fmt.Errorf("invalid tree entry: truncated hash")
		}
		hash := bytesToHex(data[i : i+20])
		i += 20

		entries = append(entries, TreeEntry{
			Mode: mode,
			Name: name,
			Hash: hash,
		})
	}

	return &Tree{Entries: entries}, nil
}

// hexToBytes는 hex 문자열을 binary로 변환합니다.
func hexToBytes(hex string) []byte {
	result := make([]byte, len(hex)/2)
	for i := 0; i < len(result); i++ {
		high := hexDigit(hex[i*2])
		low := hexDigit(hex[i*2+1])
		result[i] = (high << 4) | low
	}
	return result
}

// bytesToHex는 binary를 hex 문자열로 변환합니다.
func bytesToHex(b []byte) string {
	const hexChars = "0123456789abcdef"
	result := make([]byte, len(b)*2)
	for i, v := range b {
		result[i*2] = hexChars[v>>4]
		result[i*2+1] = hexChars[v&0xf]
	}
	return string(result)
}

func hexDigit(c byte) byte {
	switch {
	case c >= '0' && c <= '9':
		return c - '0'
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10
	case c >= 'A' && c <= 'F':
		return c - 'A' + 10
	}
	return 0
}

