package storage

import (
	"fmt"
	"strings"
	"time"
)

// Signature는 커밋 작성자/커미터 정보
type Signature struct {
	Name  string
	Email string
	When  time.Time
}

func (s Signature) String() string {
	// Git 형식: "Name <email> timestamp timezone"
	ts := s.When.Unix()
	_, offset := s.When.Zone()
	hours := offset / 3600
	mins := (offset % 3600) / 60
	return fmt.Sprintf("%s <%s> %d %+03d%02d", s.Name, s.Email, ts, hours, mins)
}

// Commit은 저장소의 특정 시점 스냅샷
type Commit struct {
	TreeHash  string    // 루트 Tree 해시
	Parents   []string  // 부모 커밋 해시 (merge는 2개 이상)
	Author    Signature
	Committer Signature
	Message   string
}

// ToObject는 Commit을 저장 가능한 Object로 변환합니다.
// Git Commit 텍스트 형식:
//   tree {hash}
//   parent {hash}   (부모가 있을 때만)
//   author {sig}
//   committer {sig}
//   (빈 줄)
//   {message}
func (c *Commit) ToObject() *Object {
	var sb strings.Builder

	sb.WriteString(fmt.Sprintf("tree %s\n", c.TreeHash))
	for _, p := range c.Parents {
		sb.WriteString(fmt.Sprintf("parent %s\n", p))
	}
	sb.WriteString(fmt.Sprintf("author %s\n", c.Author.String()))
	sb.WriteString(fmt.Sprintf("committer %s\n", c.Committer.String()))
	sb.WriteString("\n")
	sb.WriteString(c.Message)
	if !strings.HasSuffix(c.Message, "\n") {
		sb.WriteString("\n")
	}

	content := []byte(sb.String())
	return &Object{
		Type:    CommitType,
		Content: content,
		Hash:    calculateHash(CommitType, content),
	}
}

// CommitFromObject는 Object에서 Commit을 복원합니다.
func CommitFromObject(obj *Object) (*Commit, error) {
	if obj.Type != CommitType {
		return nil, fmt.Errorf("expected commit, got %s", obj.Type)
	}

	text := string(obj.Content)
	lines := strings.Split(text, "\n")

	commit := &Commit{}
	i := 0

	// 헤더 파싱 (빈 줄 전까지)
	for i < len(lines) && lines[i] != "" {
		line := lines[i]
		if strings.HasPrefix(line, "tree ") {
			commit.TreeHash = strings.TrimPrefix(line, "tree ")
		} else if strings.HasPrefix(line, "parent ") {
			commit.Parents = append(commit.Parents, strings.TrimPrefix(line, "parent "))
		} else if strings.HasPrefix(line, "author ") {
			sig, err := parseSignature(strings.TrimPrefix(line, "author "))
			if err != nil {
				return nil, fmt.Errorf("invalid author: %w", err)
			}
			commit.Author = sig
		} else if strings.HasPrefix(line, "committer ") {
			sig, err := parseSignature(strings.TrimPrefix(line, "committer "))
			if err != nil {
				return nil, fmt.Errorf("invalid committer: %w", err)
			}
			commit.Committer = sig
		}
		i++
	}
	i++ // 빈 줄 스킵

	// 커밋 메시지
	commit.Message = strings.Join(lines[i:], "\n")
	commit.Message = strings.TrimRight(commit.Message, "\n")

	return commit, nil
}

// parseSignature는 "Name <email> timestamp tz" 형식을 파싱합니다.
func parseSignature(s string) (Signature, error) {
	// "Name <email> 1234567890 +0900"
	ltIdx := strings.LastIndex(s, "<")
	gtIdx := strings.LastIndex(s, ">")
	if ltIdx < 0 || gtIdx < 0 || gtIdx < ltIdx {
		return Signature{}, fmt.Errorf("invalid signature format")
	}

	name := strings.TrimSpace(s[:ltIdx])
	email := s[ltIdx+1 : gtIdx]
	rest := strings.TrimSpace(s[gtIdx+1:])

	var ts int64
	var tz string
	_, err := fmt.Sscanf(rest, "%d %s", &ts, &tz)
	if err != nil {
		return Signature{}, fmt.Errorf("invalid timestamp: %w", err)
	}

	when := time.Unix(ts, 0)
	return Signature{Name: name, Email: email, When: when}, nil
}

