package storage

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

// IndexEntry는 스테이징 영역의 파일 항목
type IndexEntry struct {
	Path string // 저장소 내 상대 경로
	Hash string // Blob 해시
	Mode string // "100644" or "100755"
}

// Index는 git add로 쌓인 스테이징 영역
type Index struct {
	path    string
	Entries map[string]IndexEntry // path → entry
}

// LoadIndex는 인덱스 파일을 로드합니다. 없으면 빈 인덱스 반환.
func LoadIndex(repoRoot string) (*Index, error) {
	indexPath := filepath.Join(repoRoot, ".freegit", "index")
	idx := &Index{
		path:    indexPath,
		Entries: make(map[string]IndexEntry),
	}

	data, err := os.ReadFile(indexPath)
	if os.IsNotExist(err) {
		return idx, nil
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read index: %w", err)
	}

	var entries []IndexEntry
	if err := json.Unmarshal(data, &entries); err != nil {
		return nil, fmt.Errorf("failed to parse index: %w", err)
	}
	for _, e := range entries {
		idx.Entries[e.Path] = e
	}

	return idx, nil
}

// Save는 인덱스를 디스크에 저장합니다.
func (idx *Index) Save() error {
	entries := make([]IndexEntry, 0, len(idx.Entries))
	for _, e := range idx.Entries {
		entries = append(entries, e)
	}

	data, err := json.MarshalIndent(entries, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal index: %w", err)
	}

	return os.WriteFile(idx.path, data, 0644)
}

// Add는 파일을 스테이징 영역에 추가합니다.
func (idx *Index) Add(path, hash, mode string) {
	idx.Entries[path] = IndexEntry{Path: path, Hash: hash, Mode: mode}
}

// Remove는 파일을 스테이징 영역에서 제거합니다.
func (idx *Index) Remove(path string) {
	delete(idx.Entries, path)
}

// ToTreeEntries는 인덱스를 Tree 엔트리 목록으로 변환합니다.
// (현재는 평면 구조만 지원, 서브디렉토리는 추후 구현)
func (idx *Index) ToTreeEntries() []TreeEntry {
	entries := make([]TreeEntry, 0, len(idx.Entries))
	for _, e := range idx.Entries {
		entries = append(entries, TreeEntry{
			Mode: e.Mode,
			Name: e.Path,
			Hash: e.Hash,
		})
	}
	return entries
}

