	// 실제 Git과 동일한 해시 검증
	// echo -n "Hello, World!" | git hash-object --stdin → 8ab686...
	blob := storage.NewBlob([]byte("Hello, World!"))
	if blob.Type != storage.BlobType {
		t.Errorf("expected blob type, got %s", blob.Type)
	}
	if len(blob.Hash) != 40 {
		t.Errorf("expected 40-char hash, got %d: %s", len(blob.Hash), blob.Hash)
	}
}

func TestBlobSerializeDeserialize(t *testing.T) {
	content := []byte("test content 123")
	blob := storage.NewBlob(content)

	serialized := blob.Serialize()
	restored, err := storage.Deserialize(serialized)
	if err != nil {
		t.Fatalf("deserialize failed: %v", err)
	}

	if restored.Hash != blob.Hash {
		t.Errorf("hash mismatch: %s != %s", restored.Hash, blob.Hash)
	}
	if string(restored.Content) != string(content) {
		t.Errorf("content mismatch")
	}
}

func TestBlobHashConsistency(t *testing.T) {
	// 같은 내용 → 항상 같은 해시
	content := []byte("consistent content")
	b1 := storage.NewBlob(content)
	b2 := storage.NewBlob(content)
	if b1.Hash != b2.Hash {
		t.Error("same content should produce same hash")
	}

	// 다른 내용 → 다른 해시
	b3 := storage.NewBlob([]byte("different content"))
	if b1.Hash == b3.Hash {
		t.Error("different content should produce different hash")
	}
}

// --- Store 테스트 ---

func TestStoreWriteAndRead(t *testing.T) {
	dir := t.TempDir()
	store := storage.NewStore(dir)
	if err := store.Init(); err != nil {
		t.Fatalf("init failed: %v", err)
	}

	blob := storage.NewBlob([]byte("store test"))
	if err := store.Write(blob); err != nil {
		t.Fatalf("write failed: %v", err)
	}

	// 존재 확인
	if !store.Exists(blob.Hash) {
		t.Error("object should exist after write")
	}

	// 읽기
	loaded, err := store.Read(blob.Hash)
	if err != nil {
		t.Fatalf("read failed: %v", err)
	}
	if loaded.Hash != blob.Hash {
		t.Errorf("hash mismatch after read")
	}
	if string(loaded.Content) != "store test" {
		t.Errorf("content mismatch after read")
	}
}

func TestStoreIdempotentWrite(t *testing.T) {
	dir := t.TempDir()
	store := storage.NewStore(dir)
	store.Init()

	blob := storage.NewBlob([]byte("duplicate"))

	// 같은 오브젝트 두 번 써도 에러 없어야 함
	if err := store.Write(blob); err != nil {
		t.Fatalf("first write failed: %v", err)
	}
	if err := store.Write(blob); err != nil {
		t.Fatalf("second write failed: %v", err)
	}

	hashes, err := store.List()
	if err != nil {
		t.Fatalf("list failed: %v", err)
	}
	if len(hashes) != 1 {
		t.Errorf("expected 1 object, got %d", len(hashes))
	}
}

func TestStoreList(t *testing.T) {
	dir := t.TempDir()
	store := storage.NewStore(dir)
	store.Init()

	blobs := []*storage.Object{
		storage.NewBlob([]byte("file1")),
		storage.NewBlob([]byte("file2")),
		storage.NewBlob([]byte("file3")),
	}
	for _, b := range blobs {
		store.Write(b)
	}

	hashes, err := store.List()
	if err != nil {
		t.Fatalf("list failed: %v", err)
	}
	if len(hashes) != 3 {
		t.Errorf("expected 3 objects, got %d", len(hashes))
	}
}

func TestStoreReadNotFound(t *testing.T) {
	dir := t.TempDir()
	store := storage.NewStore(dir)
	store.Init()

	_, err := store.Read("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
	if err == nil {
		t.Error("expected error for non-existent object")
	}
}

// --- Tree 테스트 ---

func TestTreeSortedEntries(t *testing.T) {
	entries := []storage.TreeEntry{
		{Mode: "100644", Name: "zebra.txt", Hash: "aabbccdd" + "aabbccddaabbccddaabbccddaabbccdd"},
		{Mode: "100644", Name: "apple.txt", Hash: "11223344" + "1122334411223344112233441122334411"},
		{Mode: "100644", Name: "mango.txt", Hash: "55667788" + "5566778855667788556677885566778855"},
	}

	// 해시 길이 보정
	for i := range entries {
		for len(entries[i].Hash) < 40 {
			entries[i].Hash += "0"
		}
	}

	tree := storage.NewTree(entries)
	if tree.Entries[0].Name != "apple.txt" {
		t.Errorf("expected apple.txt first, got %s", tree.Entries[0].Name)
	}
	if tree.Entries[2].Name != "zebra.txt" {
		t.Errorf("expected zebra.txt last, got %s", tree.Entries[2].Name)
	}
}

func TestTreeToObjectAndBack(t *testing.T) {
	// 40자 더미 해시
	h1 := "da39a3ee5e6b4b0d3255bfef95601890afd80709"
	h2 := "adc83b19e793491b1c6ea0fd8b46cd9f32e592fc"

	entries := []storage.TreeEntry{
		{Mode: "100644", Name: "hello.txt", Hash: h1},
		{Mode: "100644", Name: "world.txt", Hash: h2},
	}
	tree := storage.NewTree(entries)
	obj := tree.ToObject()

	if obj.Type != storage.TreeType {
		t.Errorf("expected tree type, got %s", obj.Type)
	}

	restored, err := storage.TreeFromObject(obj)
	if err != nil {
		t.Fatalf("TreeFromObject failed: %v", err)
	}
	if len(restored.Entries) != 2 {
		t.Errorf("expected 2 entries, got %d", len(restored.Entries))
	}
	if restored.Entries[0].Name != "hello.txt" {
		t.Errorf("name mismatch: %s", restored.Entries[0].Name)
	}
	if restored.Entries[0].Hash != h1 {
		t.Errorf("hash mismatch: %s != %s", restored.Entries[0].Hash, h1)
	}
}

// --- Commit 테스트 ---

func TestCommitToObjectAndBack(t *testing.T) {
	treeHash := "da39a3ee5e6b4b0d3255bfef95601890afd80709"
	commit := &storage.Commit{
		TreeHash: treeHash,
		Parents:  []string{},
		Author: storage.Signature{
			Name:  "Kim",
			Email: "kim@freegit.local",
		},
		Committer: storage.Signature{
			Name:  "Kim",
			Email: "kim@freegit.local",
		},
		Message: "Initial commit",
	}

	obj := commit.ToObject()
	if obj.Type != storage.CommitType {
		t.Errorf("expected commit type, got %s", obj.Type)
	}

	restored, err := storage.CommitFromObject(obj)
	if err != nil {
		t.Fatalf("CommitFromObject failed: %v", err)
	}
	if restored.TreeHash != treeHash {
		t.Errorf("tree hash mismatch: %s", restored.TreeHash)
	}
	if restored.Message != "Initial commit" {
		t.Errorf("message mismatch: %s", restored.Message)
	}
	if restored.Author.Name != "Kim" {
		t.Errorf("author name mismatch: %s", restored.Author.Name)
	}
}

func TestCommitChain(t *testing.T) {
	dir := t.TempDir()
	store := storage.NewStore(dir)
	store.Init()

	treeHash := "da39a3ee5e6b4b0d3255bfef95601890afd80709"
	sig := storage.Signature{Name: "Test", Email: "test@test.com"}

	// 첫 커밋
	c1 := &storage.Commit{
		TreeHash: treeHash, Parents: []string{},
		Author: sig, Committer: sig, Message: "first",
	}
	obj1 := c1.ToObject()
	store.Write(obj1)

	// 두 번째 커밋 (c1 부모)
	c2 := &storage.Commit{
		TreeHash: treeHash, Parents: []string{obj1.Hash},
		Author: sig, Committer: sig, Message: "second",
	}
	obj2 := c2.ToObject()
	store.Write(obj2)

	// 두 번째 커밋 로드 → 부모 확인
	loaded, err := store.Read(obj2.Hash)
	if err != nil {
		t.Fatalf("read failed: %v", err)
	}
	restored, err := storage.CommitFromObject(loaded)
	if err != nil {
		t.Fatalf("restore failed: %v", err)
	}
	if len(restored.Parents) != 1 || restored.Parents[0] != obj1.Hash {
		t.Errorf("parent chain broken")
	}
}

// --- Index 테스트 ---

func TestIndexAddAndSave(t *testing.T) {
	dir := t.TempDir()
	// .freegit 폴더 필요
	os.MkdirAll(filepath.Join(dir, ".freegit"), 0755)

	idx, err := storage.LoadIndex(dir)
	if err != nil {
		t.Fatalf("load failed: %v", err)
	}

	idx.Add("README.md", "aabbccddeeff" + "0000000000000000000000000000", "100644")
	idx.Add("main.go", "11223344556677" + "00000000000000000000000000", "100644")

	if err := idx.Save(); err != nil {
		t.Fatalf("save failed: %v", err)
	}

	// 다시 로드
	idx2, err := storage.LoadIndex(dir)
	if err != nil {
		t.Fatalf("reload failed: %v", err)
	}
	if len(idx2.Entries) != 2 {
		t.Errorf("expected 2 entries, got %d", len(idx2.Entries))
	}
	if _, ok := idx2.Entries["README.md"]; !ok {
		t.Error("README.md not found in reloaded index")
	}
}

func TestIndexRemove(t *testing.T) {
	dir := t.TempDir()
	os.MkdirAll(filepath.Join(dir, ".freegit"), 0755)

	idx, _ := storage.LoadIndex(dir)
	idx.Add("file.txt", "aaaa" + "000000000000000000000000000000000000", "100644")
	idx.Remove("file.txt")

	if len(idx.Entries) != 0 {
		t.Errorf("expected empty index after remove")
	}
}

// --- 통합 테스트 ---

func TestFullWorkflow(t *testing.T) {
	dir := t.TempDir()
	store := storage.NewStore(dir)
	if err := store.Init(); err != nil {
		t.Fatalf("init failed: %v", err)
	}

	// 파일 2개 blob으로 저장
	b1 := storage.NewBlob([]byte("package main\n\nfunc main() {}"))
	b2 := storage.NewBlob([]byte("# README\n\nHello, FreeGit!"))
	store.Write(b1)
	store.Write(b2)

	// Tree 생성
	tree := storage.NewTree([]storage.TreeEntry{
		{Mode: "100644", Name: "main.go", Hash: b1.Hash},
		{Mode: "100644", Name: "README.md", Hash: b2.Hash},
	})
	treeObj := tree.ToObject()
	store.Write(treeObj)

	// Commit 생성
	sig := storage.Signature{Name: "Kim", Email: "kim@test.com"}
	commit := &storage.Commit{
		TreeHash: treeObj.Hash, Parents: []string{},
		Author: sig, Committer: sig, Message: "Init project",
	}
	commitObj := commit.ToObject()
	store.Write(commitObj)

	// 검증: 4개 오브젝트 (blob*2, tree, commit)
	hashes, _ := store.List()
	if len(hashes) != 4 {
		t.Errorf("expected 4 objects, got %d", len(hashes))
	}

	// 커밋 복원
	loaded, err := store.Read(commitObj.Hash)
	if err != nil {
		t.Fatalf("read commit failed: %v", err)
	}
	restoredCommit, err := storage.CommitFromObject(loaded)
	if err != nil {
		t.Fatalf("restore commit failed: %v", err)
	}
	if restoredCommit.TreeHash != treeObj.Hash {
		t.Errorf("tree hash mismatch")
	}

	// 트리 복원 → 파일 확인
	treeLoaded, _ := store.Read(restoredCommit.TreeHash)
	restoredTree, err := storage.TreeFromObject(treeLoaded)
	if err != nil {
		t.Fatalf("restore tree failed: %v", err)
	}
	if len(restoredTree.Entries) != 2 {
		t.Errorf("expected 2 tree entries, got %d", len(restoredTree.Entries))
	}

	// blob 내용 복원
	blobLoaded, _ := store.Read(restoredTree.Entries[0].Hash)
	if string(blobLoaded.Content) != "# README\n\nHello, FreeGit!" {
		t.Errorf("blob content mismatch: %s", string(blobLoaded.Content))
	}
}

