func TestCommitToObjectAndBack(t *testing.T) {
	treeHash := "da39a3ee5e6b4b0d3255bfef95601890afd80709"
	commit := &storage.Commit{
		TreeHash: treeHash,
		Parents:  []string{},
		Author: storage.Signature{
			Name:  "Kim",
			Email: "kim@freegit.local",
		},
		Committer: storage.Signature{
			Name:  "Kim",
			Email: "kim@freegit.local",
		},
		Message: "Initial commit",
	}

	obj := commit.ToObject()
	if obj.Type != storage.CommitType {
		t.Errorf("expected commit type, got %s", obj.Type)
	}

	restored, err := storage.CommitFromObject(obj)
	if err != nil {
		t.Fatalf("CommitFromObject failed: %v", err)
	}
	if restored.TreeHash != treeHash {
		t.Errorf("tree hash mismatch: %s", restored.TreeHash)
	}
	if restored.Message != "Initial commit" {
		t.Errorf("message mismatch: %s", restored.Message)
	}
	if restored.Author.Name != "Kim" {
		t.Errorf("author name mismatch: %s", restored.Author.Name)
	}
}

func TestCommitChain(t *testing.T) {
	dir := t.TempDir()
	store := storage.NewStore(dir)
	store.Init()

	treeHash := "da39a3ee5e6b4b0d3255bfef95601890afd80709"
	sig := storage.Signature{Name: "Test", Email: "test@test.com"}

	// 첫 커밋
	c1 := &storage.Commit{
		TreeHash: treeHash, Parents: []string{},
		Author: sig, Committer: sig, Message: "first",
	}
	obj1 := c1.ToObject()
	store.Write(obj1)

	// 두 번째 커밋 (c1 부모)
	c2 := &storage.Commit{
		TreeHash: treeHash, Parents: []string{obj1.Hash},
		Author: sig, Committer: sig, Message: "second",
	}
	obj2 := c2.ToObject()
	store.Write(obj2)

	// 두 번째 커밋 로드 → 부모 확인
	loaded, err := store.Read(obj2.Hash)
	if err != nil {
		t.Fatalf("read failed: %v", err)
	}
	restored, err := storage.CommitFromObject(loaded)
	if err != nil {
		t.Fatalf("restore failed: %v", err)
	}
	if len(restored.Parents) != 1 || restored.Parents[0] != obj1.Hash {
		t.Errorf("parent chain broken")
	}
}

// --- Index 테스트 ---

func TestIndexAddAndSave(t *testing.T) {
	dir := t.TempDir()
	// .freegit 폴더 필요
	os.MkdirAll(filepath.Join(dir, ".freegit"), 0755)

	idx, err := storage.LoadIndex(dir)
	if err != nil {
		t.Fatalf("load failed: %v", err)
	}

	idx.Add("README.md", "aabbccddeeff" + "0000000000000000000000000000", "100644")
	idx.Add("main.go", "11223344556677" + "00000000000000000000000000", "100644")

	if err := idx.Save(); err != nil {
		t.Fatalf("save failed: %v", err)
	}

	// 다시 로드
	idx2, err := storage.LoadIndex(dir)
	if err != nil {
		t.Fatalf("reload failed: %v", err)
	}
	if len(idx2.Entries) != 2 {
		t.Errorf("expected 2 entries, got %d", len(idx2.Entries))
	}
	if _, ok := idx2.Entries["README.md"]; !ok {
		t.Error("README.md not found in reloaded index")
	}
}

func TestIndexRemove(t *testing.T) {
	dir := t.TempDir()
	os.MkdirAll(filepath.Join(dir, ".freegit"), 0755)

	idx, _ := storage.LoadIndex(dir)
	idx.Add("file.txt", "aaaa" + "000000000000000000000000000000000000", "100644")
	idx.Remove("file.txt")

	if len(idx.Entries) != 0 {
		t.Errorf("expected empty index after remove")
	}
}

// --- 통합 테스트 ---

func TestFullWorkflow(t *testing.T) {
	dir := t.TempDir()
	store := storage.NewStore(dir)
	if err := store.Init(); err != nil {
		t.Fatalf("init failed: %v", err)
	}

	// 파일 2개 blob으로 저장
	b1 := storage.NewBlob([]byte("package main\n\nfunc main() {}"))
	b2 := storage.NewBlob([]byte("# README\n\nHello, FreeGit!"))
	store.Write(b1)
	store.Write(b2)

	// Tree 생성
	tree := storage.NewTree([]storage.TreeEntry{
		{Mode: "100644", Name: "main.go", Hash: b1.Hash},
		{Mode: "100644", Name: "README.md", Hash: b2.Hash},
	})
	treeObj := tree.ToObject()
	store.Write(treeObj)

	// Commit 생성
	sig := storage.Signature{Name: "Kim", Email: "kim@test.com"}
	commit := &storage.Commit{
		TreeHash: treeObj.Hash, Parents: []string{},
		Author: sig, Committer: sig, Message: "Init project",
	}
	commitObj := commit.ToObject()
	store.Write(commitObj)

	// 검증: 4개 오브젝트 (blob*2, tree, commit)
	hashes, _ := store.List()
	if len(hashes) != 4 {
		t.Errorf("expected 4 objects, got %d", len(hashes))
	}

	// 커밋 복원
	loaded, err := store.Read(commitObj.Hash)
	if err != nil {
		t.Fatalf("read commit failed: %v", err)
	}
	restoredCommit, err := storage.CommitFromObject(loaded)
	if err != nil {
		t.Fatalf("restore commit failed: %v", err)
	}
	if restoredCommit.TreeHash != treeObj.Hash {
		t.Errorf("tree hash mismatch")
	}

	// 트리 복원 → 파일 확인
	treeLoaded, _ := store.Read(restoredCommit.TreeHash)
	restoredTree, err := storage.TreeFromObject(treeLoaded)
	if err != nil {
		t.Fatalf("restore tree failed: %v", err)
	}
	if len(restoredTree.Entries) != 2 {
		t.Errorf("expected 2 tree entries, got %d", len(restoredTree.Entries))
	}

	// blob 내용 복원
	blobLoaded, _ := store.Read(restoredTree.Entries[0].Hash)
	if string(blobLoaded.Content) != "# README\n\nHello, FreeGit!" {
		t.Errorf("blob content mismatch: %s", string(blobLoaded.Content))
	}
}

