package storage

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Refs는 브랜치/태그 레퍼런스를 관리합니다.
// .freegit/refs/heads/{branch} = 커밋 해시
type Refs struct {
	root string
}

func NewRefs(root string) *Refs {
	return &Refs{root: root}
}

// refsDir는 .freegit/refs/heads 경로를 반환합니다.
func (r *Refs) refsDir() string {
	return filepath.Join(r.root, ".freegit", "refs", "heads")
}

// SetBranch는 브랜치가 가리키는 커밋 해시를 설정합니다.
func (r *Refs) SetBranch(name, hash string) error {
	path := filepath.Join(r.refsDir(), name)
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		return err
	}
	return os.WriteFile(path, []byte(hash+"\n"), 0644)
}

// GetBranch는 브랜치의 커밋 해시를 반환합니다.
func (r *Refs) GetBranch(name string) (string, error) {
	path := filepath.Join(r.refsDir(), name)
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return "", fmt.Errorf("branch not found: %s", name)
	}
	if err != nil {
		return "", err
	}
	return strings.TrimRight(string(data), "\n"), nil
}

// DeleteBranch는 브랜치를 삭제합니다.
func (r *Refs) DeleteBranch(name string) error {
	path := filepath.Join(r.refsDir(), name)
	if err := os.Remove(path); os.IsNotExist(err) {
		return fmt.Errorf("branch not found: %s", name)
	} else if err != nil {
		return err
	}
	return nil
}

// ListBranches는 모든 브랜치 이름을 반환합니다.
func (r *Refs) ListBranches() ([]string, error) {
	entries, err := os.ReadDir(r.refsDir())
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	var branches []string
	for _, e := range entries {
		if !e.IsDir() {
			branches = append(branches, e.Name())
		}
	}
	return branches, nil
}

// CurrentBranch는 HEAD가 가리키는 브랜치 이름을 반환합니다.
// detached HEAD이면 빈 문자열 반환.
func (r *Refs) CurrentBranch() (string, error) {
	headPath := filepath.Join(r.root, ".freegit", "HEAD")
	data, err := os.ReadFile(headPath)
	if err != nil {
		return "", err
	}
	content := strings.TrimRight(string(data), "\n")
	if strings.HasPrefix(content, "ref: refs/heads/") {
		return strings.TrimPrefix(content, "ref: refs/heads/"), nil
	}
	return "", nil // detached HEAD
}

// SetHEAD는 HEAD를 브랜치 또는 직접 커밋 해시로 설정합니다.
func (r *Refs) SetHEAD(target string, isBranch bool) error {
	headPath := filepath.Join(r.root, ".freegit", "HEAD")
	var content string
	if isBranch {
		content = "ref: refs/heads/" + target + "\n"
	} else {
		content = target + "\n"
	}
	return os.WriteFile(headPath, []byte(content), 0644)
}

// ResolveHEAD는 HEAD가 가리키는 커밋 해시를 반환합니다.
func (r *Refs) ResolveHEAD() (string, error) {
	headPath := filepath.Join(r.root, ".freegit", "HEAD")
	data, err := os.ReadFile(headPath)
	if err != nil {
		return "", err
	}
	content := strings.TrimRight(string(data), "\n")
	if strings.HasPrefix(content, "ref: ") {
		refPath := filepath.Join(r.root, ".freegit", content[5:])
		refData, err := os.ReadFile(refPath)
		if os.IsNotExist(err) {
			return "", nil
		}
		if err != nil {
			return "", err
		}
		return strings.TrimRight(string(refData), "\n"), nil
	}
	return content, nil
}

