package storage

import (
	"fmt"
	"os"
	"path/filepath"
)

// Checkout은 커밋의 Tree를 워킹 디렉토리에 복원합니다.
// 실제 Git checkout과 동일:
//   1. 커밋 → Tree 해시 조회
//   2. Tree 엔트리 → Blob 내용 복원
//   3. 워킹 디렉토리 파일 덮어쓰기
type Checkout struct {
	store *Store
	root  string
}

func NewCheckout(store *Store, root string) *Checkout {
	return &Checkout{store: store, root: root}
}

// RestoreCommit은 커밋 해시로 워킹 디렉토리를 복원합니다.
// force=true면 수정된 파일도 덮어씁니다.
func (c *Checkout) RestoreCommit(commitHash string) ([]string, error) {
	// 1. 커밋 로드
	commitObj, err := c.store.Read(commitHash)
	if err != nil {
		return nil, fmt.Errorf("commit not found: %s", commitHash)
	}
	commit, err := CommitFromObject(commitObj)
	if err != nil {
		return nil, fmt.Errorf("invalid commit: %w", err)
	}

	// 2. Tree 로드
	treeObj, err := c.store.Read(commit.TreeHash)
	if err != nil {
		return nil, fmt.Errorf("tree not found: %s", commit.TreeHash)
	}
	tree, err := TreeFromObject(treeObj)
	if err != nil {
		return nil, fmt.Errorf("invalid tree: %w", err)
	}

	// 3. 각 파일 복원
	var restored []string
	for _, entry := range tree.Entries {
		blobObj, err := c.store.Read(entry.Hash)
		if err != nil {
			return nil, fmt.Errorf("blob not found for %s: %w", entry.Name, err)
		}

		filePath := filepath.Join(c.root, entry.Name)
		if err := os.MkdirAll(filepath.Dir(filePath), 0755); err != nil {
			return nil, fmt.Errorf("failed to create dir for %s: %w", entry.Name, err)
		}

		perm := os.FileMode(0644)
		if entry.Mode == "100755" {
			perm = 0755
		}

		if err := os.WriteFile(filePath, blobObj.Content, perm); err != nil {
			return nil, fmt.Errorf("failed to restore %s: %w", entry.Name, err)
		}
		restored = append(restored, entry.Name)
	}

	return restored, nil
}

// Diff는 현재 워킹 디렉토리와 커밋의 Tree를 비교합니다.
// 수정된 파일 목록을 반환합니다.
func (c *Checkout) Diff(commitHash string) (added, modified, deleted []string, err error) {
	commitObj, err := c.store.Read(commitHash)
	if err != nil {
		return nil, nil, nil, fmt.Errorf("commit not found: %s", commitHash)
	}
	commit, err := CommitFromObject(commitObj)
	if err != nil {
		return nil, nil, nil, err
	}
	treeObj, err := c.store.Read(commit.TreeHash)
	if err != nil {
		return nil, nil, nil, err
	}
	tree, err := TreeFromObject(treeObj)
	if err != nil {
		return nil, nil, nil, err
	}

	// Tree 엔트리를 맵으로
	tracked := make(map[string]string) // path → hash
	for _, e := range tree.Entries {
		tracked[e.Name] = e.Hash
	}

	// 워킹 디렉토리 파일 확인
	for name, hash := range tracked {
		filePath := filepath.Join(c.root, name)
		data, err := os.ReadFile(filePath)
		if os.IsNotExist(err) {
			deleted = append(deleted, name)
			continue
		}
		if err != nil {
			continue
		}
		currentBlob := NewBlob(data)
		if currentBlob.Hash != hash {
			modified = append(modified, name)
		}
	}

	// 워킹 디렉토리에만 있는 파일 (untracked는 별도 처리)
	_ = added

	return added, modified, deleted, nil
}

