type Merger struct {
	store *Store
}

func NewMerger(store *Store) *Merger {
	return &Merger{store: store}
}

// FastForward는 현재 HEAD에서 target 커밋으로 fast-forward 가능한지 확인하고 실행합니다.
// Fast-Forward 조건: target이 current의 자손이어야 함
func (m *Merger) FastForward(currentHash, targetHash string) (*MergeResult, error) {
	if currentHash == targetHash {
		return &MergeResult{
			Type:    MergeAlreadyUpToDate,
			Message: "Already up to date.",
		}, nil
	}

	// target이 current의 자손인지 확인
	isDescendant, err := m.isAncestor(currentHash, targetHash)
	if err != nil {
		return nil, err
	}
	if !isDescendant {
		return &MergeResult{
			Type:    MergeConflict,
			Message: "Automatic merge failed. Non-fast-forward merge not yet supported.",
		}, nil
	}

	return &MergeResult{
		Type:       MergeFastForward,
		CommitHash: targetHash,
		Message:    fmt.Sprintf("Fast-forward to %s", targetHash[:8]),
	}, nil
}

// isAncestor는 ancestor가 descendant의 조상인지 확인합니다.
// BFS로 커밋 히스토리를 탐색합니다.
func (m *Merger) isAncestor(ancestor, descendant string) (bool, error) {
	if ancestor == "" {
		return true, nil // 빈 해시 = 루트, 항상 조상
	}

	visited := make(map[string]bool)
	queue := []string{descendant}

	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]

		if current == ancestor {
			return true, nil
		}
		if visited[current] {
			continue
		}
		visited[current] = true

		obj, err := m.store.Read(current)
		if err != nil {
			return false, nil // 오브젝트 없으면 탐색 중단
		}
		commit, err := CommitFromObject(obj)
		if err != nil {
			continue
		}
		queue = append(queue, commit.Parents...)
	}

	return false, nil
}

// CommitHistory는 특정 커밋에서 루트까지의 전체 해시 목록을 반환합니다.
func (m *Merger) CommitHistory(startHash string) ([]string, error) {
	var history []string
	visited := make(map[string]bool)
	queue := []string{startHash}

	for len(queue) > 0 {
		hash := queue[0]
		queue = queue[1:]

		if hash == "" || visited[hash] {
			continue
		}
		visited[hash] = true
		history = append(history, hash)

		obj, err := m.store.Read(hash)
		if err != nil {
			break
		}
		commit, err := CommitFromObject(obj)
		if err != nil {
			break
		}
		queue = append(queue, commit.Parents...)
	}

	return history, nil
}

