package main

import (
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/kim/git-from-scratch/storage"
)

func main() {
	if len(os.Args) < 2 {
		printUsage()
		os.Exit(1)
	}

	cmd := os.Args[1]
	args := os.Args[2:]

	var err error
	switch cmd {
	case "init":
		err = cmdInit(args)
	case "hash-object":
		err = cmdHashObject(args)
	case "cat-file":
		err = cmdCatFile(args)
	case "add":
		err = cmdAdd(args)
	case "commit":
		err = cmdCommit(args)
	case "log":
		err = cmdLog(args)
	case "status":
		err = cmdStatus(args)
	default:
		fmt.Fprintf(os.Stderr, "unknown command: %s\n", cmd)
		printUsage()
		os.Exit(1)
	}

	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
}

func printUsage() {
	fmt.Println(`git-fs - Git From Scratch v0.1.0

Usage: git-fs <command> [args]

Commands:
  init                   Initialize a new repository
  hash-object <file>     Compute SHA1 hash of a file
  cat-file <hash>        Show object content
  add <file>             Stage a file
  commit -m <message>    Create a commit
  log                    Show commit history
  status                 Show staging area`)
}

func cmdInit(args []string) error {
	root := "."
	if len(args) > 0 {
		root = args[0]
	}
	absRoot, err := filepath.Abs(root)
	if err != nil {
		return err
	}
	store := storage.NewStore(absRoot)
	if err := store.Init(); err != nil {
		return err
	}
	fmt.Printf("Initialized empty FreeGit repository in %s/.freegit/\n", absRoot)
	return nil
}

func cmdHashObject(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("usage: hash-object [-w] <file>")
	}
	write := false
	filePath := args[0]
	if args[0] == "-w" {
		if len(args) < 2 {
			return fmt.Errorf("usage: hash-object [-w] <file>")
		}
		write = true
		filePath = args[1]
	}
	content, err := os.ReadFile(filePath)
	if err != nil {
		return fmt.Errorf("failed to read file: %w", err)
	}
	blob := storage.NewBlob(content)
	fmt.Println(blob.Hash)
	if write {
		root, err := findRepoRoot(".")
		if err != nil {
			return err
		}
		store := storage.NewStore(root)
		if err := store.Write(blob); err != nil {
			return fmt.Errorf("failed to write object: %w", err)
		}
	}
	return nil
}

func cmdCatFile(args []string) error {
	if len(args) < 2 {
		return fmt.Errorf("usage: cat-file (-t|-s|-p) <hash>")
	}
	flag := args[0]
	hash := args[1]
	root, err := findRepoRoot(".")
	if err != nil {
		return err
	}
	store := storage.NewStore(root)
	obj, err := store.Read(hash)
	if err != nil {
		return err
	}
	switch flag {
	case "-t":
		fmt.Println(obj.Type)
	case "-s":
		fmt.Println(obj.Size())
	case "-p":
		fmt.Print(string(obj.Content))
	default:
		return fmt.Errorf("unknown flag: %s (use -t, -s, or -p)", flag)
	}
	return nil
}

func cmdAdd(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("usage: add <file>...")
	}
	root, err := findRepoRoot(".")
	if err != nil {
		return err
	}
	store := storage.NewStore(root)
	index, err := storage.LoadIndex(root)
	if err != nil {
		return err
	}
	for _, filePath := range args {
		absPath, _ := filepath.Abs(filePath)
		content, err := os.ReadFile(absPath)
		if err != nil {
			return fmt.Errorf("failed to read %s: %w", filePath, err)
		}
		blob := storage.NewBlob(content)
		if err := store.Write(blob); err != nil {
			return fmt.Errorf("failed to store %s: %w", filePath, err)
		}
		mode := "100644"
		if info, err := os.Stat(absPath); err == nil {
			if info.Mode()&0111 != 0 {
				mode = "100755"
			}
		}
		relPath, err := filepath.Rel(root, absPath)
		if err != nil {
			relPath = filePath
		}
		index.Add(relPath, blob.Hash, mode)
		fmt.Printf("staged: %s (%s)\n", relPath, blob.Hash[:8])
	}
	return index.Save()
}

func cmdCommit(args []string) error {
	message := ""
	for i, arg := range args {
		if arg == "-m" && i+1 < len(args) {
			message = args[i+1]
			break
		}
	}
	if message == "" {
		return fmt.Errorf("usage: commit -m <message>")
	}
	root, err := findRepoRoot(".")
	if err != nil {
		return err
	}
	store := storage.NewStore(root)
	index, err := storage.LoadIndex(root)
	if err != nil {
		return err
	}
	if len(index.Entries) == 0 {
		return fmt.Errorf("nothing to commit (staging area is empty)")
	}

	tree := storage.NewTree(index.ToTreeEntries())
	treeObj := tree.ToObject()
	if err := store.Write(treeObj); err != nil {
		return fmt.Errorf("failed to write tree: %w", err)
	}

	parents := []string{}
	headHash, err := readHEAD(root)
	if err == nil && headHash != "" {
		parents = append(parents, headHash)
	}

	now := time.Now()
	sig := storage.Signature{
		Name:  getEnv("GIT_AUTHOR_NAME", "FreeGit User"),
		Email: getEnv("GIT_AUTHOR_EMAIL", "user@freegit.local"),
		When:  now,
	}
	commit := &storage.Commit{
		TreeHash:  treeObj.Hash,
		Parents:   parents,
		Author:    sig,
		Committer: sig,
		Message:   message,
	}
	commitObj := commit.ToObject()
	if err := store.Write(commitObj); err != nil {
		return fmt.Errorf("failed to write commit: %w", err)
	}
	if err := updateHEAD(root, commitObj.Hash); err != nil {
		return fmt.Errorf("failed to update HEAD: %w", err)
	}
	index.Entries = make(map[string]storage.IndexEntry)
	if err := index.Save(); err != nil {
		return fmt.Errorf("failed to clear index: %w", err)
	}
	short := commitObj.Hash
	if len(short) > 8 {
		short = short[:8]
	}
	fmt.Printf("[main %s] %s\n", short, message)
	fmt.Printf(" %d file(s) changed\n", len(tree.Entries))
	return nil
}

func cmdLog(args []string) error {
	root, err := findRepoRoot(".")
	if err != nil {
		return err
	}
	store := storage.NewStore(root)
	hash, err := readHEAD(root)
	if err != nil || hash == "" {
		fmt.Println("(no commits yet)")
		return nil
	}
	for hash != "" {
		obj, err := store.Read(hash)
		if err != nil {
			break
		}
		commit, err := storage.CommitFromObject(obj)
		if err != nil {
			break
		}
		fmt.Printf("commit %s\n", hash)
		fmt.Printf("Author: %s <%s>\n", commit.Author.Name, commit.Author.Email)
		fmt.Printf("Date:   %s\n", commit.Author.When.Format("Mon Jan 2 15:04:05 2006 -0700"))
		fmt.Printf("\n    %s\n\n", commit.Message)
		if len(commit.Parents) > 0 {
			hash = commit.Parents[0]
		} else {
			break
		}
	}
	return nil
}

func cmdStatus(args []string) error {
	root, err := findRepoRoot(".")
	if err != nil {
		return err
	}
	index, err := storage.LoadIndex(root)
	if err != nil {
		return err
	}
	headHash, _ := readHEAD(root)
	fmt.Println("On branch main")
	if headHash == "" {
		fmt.Println("No commits yet")
	}
	if len(index.Entries) > 0 {
		fmt.Println("\nChanges to be committed:")
		for path := range index.Entries {
			fmt.Printf("  new file: %s\n", path)
		}
	} else {
		fmt.Println("nothing to commit, working tree clean")
	}
	return nil
}

// --- helpers ---

func findRepoRoot(start string) (string, error) {
	abs, err := filepath.Abs(start)
	if err != nil {
		return "", err
	}
	for {
		if _, err := os.Stat(filepath.Join(abs, ".freegit")); err == nil {
			return abs, nil
		}
		parent := filepath.Dir(abs)
		if parent == abs {
			return "", fmt.Errorf("not a FreeGit repository (no .freegit found)")
		}
		abs = parent
	}
}

func readHEAD(root string) (string, error) {
	headPath := filepath.Join(root, ".freegit", "HEAD")
	data, err := os.ReadFile(headPath)
	if err != nil {
		return "", err
	}
	content := string(data)
	if len(content) > 5 && content[:5] == "ref: " {
		refPath := filepath.Join(root, ".freegit", content[5:len(content)-1])
		refData, err := os.ReadFile(refPath)
		if os.IsNotExist(err) {
			return "", nil
		}
		if err != nil {
			return "", err
		}
		return string(refData[:len(refData)-1]), nil
	}
	if len(content) > 0 {
		return content[:len(content)-1], nil
	}
	return content, nil
}

func updateHEAD(root, hash string) error {
	headPath := filepath.Join(root, ".freegit", "HEAD")
	data, err := os.ReadFile(headPath)
	if err != nil {
		return err
	}
	content := string(data)
	if len(content) > 5 && content[:5] == "ref: " {
		refPath := filepath.Join(root, ".freegit", content[5:len(content)-1])
		if err := os.MkdirAll(filepath.Dir(refPath), 0755); err != nil {
			return err
		}
		return os.WriteFile(refPath, []byte(hash+"\n"), 0644)
	}
	return os.WriteFile(headPath, []byte(hash+"\n"), 0644)
}

func getEnv(key, defaultVal string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return defaultVal
}

