// cmdBranch: 브랜치 목록/생성/삭제
func cmdBranch(args []string) error {
	root, err := findRepoRoot(".")
	if err != nil {
		return err
	}
	refs := storage.NewRefs(root)

	// branch -d <name>: 삭제
	if len(args) == 2 && args[0] == "-d" {
		current, _ := refs.CurrentBranch()
		if current == args[1] {
			return fmt.Errorf("cannot delete the currently checked out branch: %s", args[1])
		}
		if err := refs.DeleteBranch(args[1]); err != nil {
			return err
		}
		fmt.Printf("Deleted branch %s\n", args[1])
		return nil
	}

	// branch <name>: 생성
	if len(args) == 1 && args[0] != "-d" {
		headHash, err := refs.ResolveHEAD()
		if err != nil || headHash == "" {
			return fmt.Errorf("cannot create branch: no commits yet")
		}
		if err := refs.SetBranch(args[0], headHash); err != nil {
			return err
		}
		fmt.Printf("Created branch %s → %s\n", args[0], headHash[:8])
		return nil
	}

	// branch: 목록 출력
	branches, err := refs.ListBranches()
	if err != nil {
		return err
	}
	current, _ := refs.CurrentBranch()
	if len(branches) == 0 {
		fmt.Println("(no branches)")
		return nil
	}
	for _, b := range branches {
		prefix := "  "
		if b == current {
			prefix = "* "
		}
		hash, _ := refs.GetBranch(b)
		short := hash
		if len(short) > 8 {
			short = short[:8]
		}
		fmt.Printf("%s%s  %s\n", prefix, b, short)
	}
	return nil
}

// cmdCheckout: 브랜치 전환 또는 생성
func cmdCheckout(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("usage: checkout [-b] <branch>")
	}

	root, err := findRepoRoot(".")
	if err != nil {
		return err
	}

	refs := storage.NewRefs(root)
	store := storage.NewStore(root)
	co := storage.NewCheckout(store, root)

	createNew := false
	branchName := args[0]
	if args[0] == "-b" {
		if len(args) < 2 {
			return fmt.Errorf("usage: checkout -b <branch>")
		}
		createNew = true
		branchName = args[1]
	}

	currentBranch, _ := refs.CurrentBranch()
	if !createNew && branchName == currentBranch {
		fmt.Printf("Already on '%s'\n", branchName)
		return nil
	}

	var targetHash string

	if createNew {
		// 현재 HEAD에서 새 브랜치 생성
		headHash, err := refs.ResolveHEAD()
		if err != nil || headHash == "" {
			return fmt.Errorf("cannot create branch: no commits yet")
		}
		if err := refs.SetBranch(branchName, headHash); err != nil {
			return err
		}
		targetHash = headHash
	} else {
		// 기존 브랜치로 전환
		targetHash, err = refs.GetBranch(branchName)
		if err != nil {
			return fmt.Errorf("branch not found: %s", branchName)
		}
	}

	// 워킹 디렉토리 복원
	restored, err := co.RestoreCommit(targetHash)
	if err != nil {
		return fmt.Errorf("failed to restore working directory: %w", err)
	}

	// HEAD를 새 브랜치로 변경
	if err := refs.SetHEAD(branchName, true); err != nil {
		return err
	}

	if createNew {
		fmt.Printf("Switched to a new branch '%s'\n", branchName)
	} else {
		fmt.Printf("Switched to branch '%s'\n", branchName)
	}
	fmt.Printf(" %d file(s) restored\n", len(restored))
	return nil
}

// cmdMerge: 브랜치 병합 (fast-forward)
func cmdMerge(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("usage: merge <branch>")
	}
	targetBranch := args[0]

	root, err := findRepoRoot(".")
	if err != nil {
		return err
	}

	refs := storage.NewRefs(root)
	store := storage.NewStore(root)
	merger := storage.NewMerger(store)
	co := storage.NewCheckout(store, root)

	// 현재 HEAD 해시
	currentHash, err := refs.ResolveHEAD()
	if err != nil {
		return err
	}

	// 대상 브랜치 해시
	targetHash, err := refs.GetBranch(targetBranch)
	if err != nil {
		return fmt.Errorf("branch not found: %s", targetBranch)
	}

	// 머지 시도
	result, err := merger.FastForward(currentHash, targetHash)
	if err != nil {
		return err
	}

	switch result.Type {
	case storage.MergeAlreadyUpToDate:
		fmt.Println(result.Message)

	case storage.MergeFastForward:
		// 워킹 디렉토리 복원
		restored, err := co.RestoreCommit(result.CommitHash)
		if err != nil {
			return err
		}

		// 현재 브랜치 포인터 업데이트
		currentBranch, _ := refs.CurrentBranch()
		if currentBranch != "" {
			refs.SetBranch(currentBranch, result.CommitHash)
		}

		fmt.Printf("Fast-forward\n")
		fmt.Printf(" %d file(s) updated\n", len(restored))
		fmt.Printf("%s..%s\n", currentHash[:8], result.CommitHash[:8])

	case storage.MergeConflict:
		fmt.Println(result.Message)
		return fmt.Errorf("merge failed")
	}

	return nil
}

