package tests

import (
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/kim/git-from-scratch/storage"
)

// 테스트용 저장소 초기화 + 커밋 1개 생성 헬퍼
func setupRepo(t *testing.T) (string, *storage.Store, string) {
	t.Helper()
	dir := t.TempDir()
	store := storage.NewStore(dir)
	if err := store.Init(); err != nil {
		t.Fatalf("init failed: %v", err)
	}

	// 파일 blob
	blob := storage.NewBlob([]byte("hello world"))
	store.Write(blob)

	// tree
	tree := storage.NewTree([]storage.TreeEntry{
		{Mode: "100644", Name: "hello.txt", Hash: blob.Hash},
	})
	treeObj := tree.ToObject()
	store.Write(treeObj)

	// commit
	sig := storage.Signature{Name: "Test", Email: "test@test.com", When: time.Now()}
	commit := &storage.Commit{
		TreeHash: treeObj.Hash, Parents: []string{},
		Author: sig, Committer: sig, Message: "initial",
	}
	commitObj := commit.ToObject()
	store.Write(commitObj)

	// main 브랜치 설정
	refs := storage.NewRefs(dir)
	refs.SetBranch("main", commitObj.Hash)
	refs.SetHEAD("main", true)

	return dir, store, commitObj.Hash
}

// 두 번째 커밋 생성 헬퍼
func addCommit(t *testing.T, dir string, store *storage.Store, parentHash, msg, content string) string {
	t.Helper()
	blob := storage.NewBlob([]byte(content))
	store.Write(blob)
	tree := storage.NewTree([]storage.TreeEntry{
		{Mode: "100644", Name: "file.txt", Hash: blob.Hash},
	})
	treeObj := tree.ToObject()
	store.Write(treeObj)

	sig := storage.Signature{Name: "Test", Email: "test@test.com", When: time.Now()}
	parents := []string{}
	if parentHash != "" {
		parents = []string{parentHash}
	}
	commit := &storage.Commit{
		TreeHash: treeObj.Hash, Parents: parents,
		Author: sig, Committer: sig, Message: msg,
	}
	obj := commit.ToObject()
	store.Write(obj)
	return obj.Hash
}

// --- Refs 테스트 ---

func TestRefsSetAndGet(t *testing.T) {
	dir := t.TempDir()
	os.MkdirAll(filepath.Join(dir, ".freegit", "refs", "heads"), 0755)
	refs := storage.NewRefs(dir)

	hash := "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
	if err := refs.SetBranch("main", hash); err != nil {
		t.Fatalf("SetBranch failed: %v", err)
	}

	got, err := refs.GetBranch("main")
	if err != nil {
		t.Fatalf("GetBranch failed: %v", err)
	}
	if got != hash {
		t.Errorf("expected %s, got %s", hash, got)
	}
}

func TestRefsListBranches(t *testing.T) {
	dir, _, _ := setupRepo(t)
	refs := storage.NewRefs(dir)

	refs.SetBranch("feature-a", "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
	refs.SetBranch("feature-b", "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb")

	branches, err := refs.ListBranches()
	if err != nil {
		t.Fatalf("ListBranches failed: %v", err)
	}
	if len(branches) < 3 { // main + feature-a + feature-b
		t.Errorf("expected at least 3 branches, got %d", len(branches))
	}
}

func TestRefsDeleteBranch(t *testing.T) {
	dir, _, _ := setupRepo(t)
	refs := storage.NewRefs(dir)

	refs.SetBranch("temp", "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
	if err := refs.DeleteBranch("temp"); err != nil {
		t.Fatalf("delete failed: %v", err)
	}
	_, err := refs.GetBranch("temp")
	if err == nil {
		t.Error("expected error after delete")
	}
}

func TestRefsDeleteNotFound(t *testing.T) {
	dir, _, _ := setupRepo(t)
	refs := storage.NewRefs(dir)
	if err := refs.DeleteBranch("nonexistent"); err == nil {
		t.Error("expected error for nonexistent branch")
	}
}

func TestRefsCurrentBranch(t *testing.T) {
	dir, _, _ := setupRepo(t)
	refs := storage.NewRefs(dir)

	branch, err := refs.CurrentBranch()
	if err != nil {
		t.Fatalf("CurrentBranch failed: %v", err)
	}
	if branch != "main" {
		t.Errorf("expected main, got %s", branch)
	}
}

func TestRefsSetHEADDetached(t *testing.T) {
	dir, _, commitHash := setupRepo(t)
	refs := storage.NewRefs(dir)

	// detached HEAD
	if err := refs.SetHEAD(commitHash, false); err != nil {
		t.Fatalf("SetHEAD failed: %v", err)
	}
	branch, _ := refs.CurrentBranch()
	if branch != "" {
		t.Errorf("expected empty branch for detached HEAD, got %s", branch)
	}
	resolved, err := refs.ResolveHEAD()
	if err != nil {
		t.Fatalf("ResolveHEAD failed: %v", err)
	}
	if resolved != commitHash {
		t.Errorf("expected %s, got %s", commitHash, resolved)
	}
}

// --- Checkout 테스트 ---

func TestCheckoutRestoreFiles(t *testing.T) {
	dir, store, commitHash := setupRepo(t)
	co := storage.NewCheckout(store, dir)

	// 파일이 복원되는지 확인
	restored, err := co.RestoreCommit(commitHash)
	if err != nil {
		t.Fatalf("RestoreCommit failed: %v", err)
	}
	if len(restored) != 1 {
		t.Errorf("expected 1 file restored, got %d", len(restored))
	}

	// 실제 파일 내용 확인
	content, err := os.ReadFile(filepath.Join(dir, "hello.txt"))
	if err != nil {
		t.Fatalf("file not restored: %v", err)
	}
	if string(content) != "hello world" {
		t.Errorf("wrong content: %s", string(content))
	}
}

func TestCheckoutDiff(t *testing.T) {
	dir, store, commitHash := setupRepo(t)
	co := storage.NewCheckout(store, dir)

	// 파일 복원
	co.RestoreCommit(commitHash)

	// 파일 수정
	os.WriteFile(filepath.Join(dir, "hello.txt"), []byte("modified"), 0644)

	_, modified, _, err := co.Diff(commitHash)
	if err != nil {
		t.Fatalf("Diff failed: %v", err)
	}
	if len(modified) != 1 {
		t.Errorf("expected 1 modified file, got %d", len(modified))
	}
}

func TestCheckoutNotFound(t *testing.T) {
	dir, store, _ := setupRepo(t)
	co := storage.NewCheckout(store, dir)

	_, err := co.RestoreCommit("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
	if err == nil {
		t.Error("expected error for non-existent commit")
	}
}

// --- Merge 테스트 ---

func TestMergeAlreadyUpToDate(t *testing.T) {
	_, store, commitHash := setupRepo(t)
	merger := storage.NewMerger(store)

	result, err := merger.FastForward(commitHash, commitHash)
	if err != nil {
		t.Fatalf("FastForward failed: %v", err)
	}
	if result.Type != storage.MergeAlreadyUpToDate {
		t.Errorf("expected AlreadyUpToDate, got %d", result.Type)
	}
}

func TestMergeFastForward(t *testing.T) {
	dir, store, c1Hash := setupRepo(t)
	merger := storage.NewMerger(store)

	// c1 → c2 (선형 히스토리)
	c2Hash := addCommit(t, dir, store, c1Hash, "second", "v2")

	result, err := merger.FastForward(c1Hash, c2Hash)
	if err != nil {
		t.Fatalf("FastForward failed: %v", err)
	}
	if result.Type != storage.MergeFastForward {
		t.Errorf("expected FastForward, got %d", result.Type)
	}
	if result.CommitHash != c2Hash {
		t.Errorf("expected %s, got %s", c2Hash, result.CommitHash)
	}
}

func TestMergeNonFastForward(t *testing.T) {
	dir, store, c1Hash := setupRepo(t)
	merger := storage.NewMerger(store)

	// c1 → c2, c1 → c3 (diverged)
	c2Hash := addCommit(t, dir, store, c1Hash, "branch-a", "v2")
	c3Hash := addCommit(t, dir, store, c1Hash, "branch-b", "v3")

	result, err := merger.FastForward(c2Hash, c3Hash)
	if err != nil {
		t.Fatalf("FastForward failed: %v", err)
	}
	if result.Type != storage.MergeConflict {
		t.Errorf("expected Conflict for diverged branches, got %d", result.Type)
	}
}

func TestMergeIsAncestor(t *testing.T) {
	dir, store, c1Hash := setupRepo(t)
	merger := storage.NewMerger(store)

	c2Hash := addCommit(t, dir, store, c1Hash, "c2", "v2")
	c3Hash := addCommit(t, dir, store, c2Hash, "c3", "v3")

	// c1 → c2 → c3: c1은 c3의 조상
	result, err := merger.FastForward(c1Hash, c3Hash)
	if err != nil {
		t.Fatalf("error: %v", err)
	}
	if result.Type != storage.MergeFastForward {
		t.Errorf("c1 should be ancestor of c3")
	}
}

func TestMergeCommitHistory(t *testing.T) {
	dir, store, c1Hash := setupRepo(t)
	merger := storage.NewMerger(store)

	c2Hash := addCommit(t, dir, store, c1Hash, "c2", "v2")
	c3Hash := addCommit(t, dir, store, c2Hash, "c3", "v3")

	history, err := merger.CommitHistory(c3Hash)
	if err != nil {
		t.Fatalf("CommitHistory failed: %v", err)
	}
	if len(history) != 3 {
		t.Errorf("expected 3 commits in history, got %d", len(history))
	}
}

// --- 통합 테스트: branch + checkout + merge 워크플로우 ---

func TestFullBranchWorkflow(t *testing.T) {
	dir, store, c1Hash := setupRepo(t)
	refs := storage.NewRefs(dir)
	co := storage.NewCheckout(store, dir)
	merger := storage.NewMerger(store)

	// 1. feature 브랜치 생성
	if err := refs.SetBranch("feature", c1Hash); err != nil {
		t.Fatalf("create feature branch: %v", err)
	}

	// 2. feature 브랜치로 전환
	refs.SetHEAD("feature", true)
	branch, _ := refs.CurrentBranch()
	if branch != "feature" {
		t.Errorf("expected feature branch, got %s", branch)
	}

	// 3. feature 브랜치에 커밋 추가
	featureHash := addCommit(t, dir, store, c1Hash, "feature work", "feature content")
	refs.SetBranch("feature", featureHash)

	// 4. main으로 전환 후 merge
	refs.SetHEAD("main", true)
	result, err := merger.FastForward(c1Hash, featureHash)
	if err != nil {
		t.Fatalf("merge failed: %v", err)
	}
	if result.Type != storage.MergeFastForward {
		t.Errorf("expected fast-forward merge")
	}

	// 5. 워킹 디렉토리 복원
	restored, err := co.RestoreCommit(result.CommitHash)
	if err != nil {
		t.Fatalf("restore failed: %v", err)
	}
	if len(restored) == 0 {
		t.Error("expected files to be restored")
	}

	// 6. main 포인터 업데이트
	refs.SetBranch("main", result.CommitHash)
	mainHash, _ := refs.GetBranch("main")
	if mainHash != featureHash {
		t.Errorf("main should point to feature commit after merge")
	}
}

