// --- 통합 테스트: branch + checkout + merge 워크플로우 ---

func TestFullBranchWorkflow(t *testing.T) {
	dir, store, c1Hash := setupRepo(t)
	refs := storage.NewRefs(dir)
	co := storage.NewCheckout(store, dir)
	merger := storage.NewMerger(store)

	// 1. feature 브랜치 생성
	if err := refs.SetBranch("feature", c1Hash); err != nil {
		t.Fatalf("create feature branch: %v", err)
	}

	// 2. feature 브랜치로 전환
	refs.SetHEAD("feature", true)
	branch, _ := refs.CurrentBranch()
	if branch != "feature" {
		t.Errorf("expected feature branch, got %s", branch)
	}

	// 3. feature 브랜치에 커밋 추가
	featureHash := addCommit(t, dir, store, c1Hash, "feature work", "feature content")
	refs.SetBranch("feature", featureHash)

	// 4. main으로 전환 후 merge
	refs.SetHEAD("main", true)
	result, err := merger.FastForward(c1Hash, featureHash)
	if err != nil {
		t.Fatalf("merge failed: %v", err)
	}
	if result.Type != storage.MergeFastForward {
		t.Errorf("expected fast-forward merge")
	}

	// 5. 워킹 디렉토리 복원
	restored, err := co.RestoreCommit(result.CommitHash)
	if err != nil {
		t.Fatalf("restore failed: %v", err)
	}
	if len(restored) == 0 {
		t.Error("expected files to be restored")
	}

	// 6. main 포인터 업데이트
	refs.SetBranch("main", result.CommitHash)
	mainHash, _ := refs.GetBranch("main")
	if mainHash != featureHash {
		t.Errorf("main should point to feature commit after merge")
	}
}
